import{_ as r,a0 as n,w as S,s,ao as d,I as t,x as i,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"AWS 云服务清单 | LCTT x X-CMD","titleTemplate":false,"description":"AWS 云服务清单 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"AWS 云服务清单 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"AWS 云服务清单 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170317 AWS cloud terminology","title":"AWS 云服务清单","tag":"201706","desc":""},"relativePath":"201706/20170317 AWS cloud terminology.md","filePath":"[post].md"}'),h={name:"201706/20170317 AWS cloud terminology.md"};function p(A,l,W,m,c,b){const a=n("Link");return S(),s("div",null,[l[13]||(l[13]=d('<h1 id="aws-云服务清单" tabindex="-1">AWS 云服务清单 <a class="header-anchor" href="#aws-云服务清单" aria-label="Permalink to “AWS 云服务清单”">​</a></h1><p><img src="http://cdn2.kerneltalks.com/wp-content/uploads/2017/03/AWS-Cloud-terminology-150x150.png" alt="AWS Cloud terminology"></p><p><em>认识 71 个 AWS 云服务的术语 ! 通过了解 AWS 世界中使用的术语开始你的 AWS 云服务使用生涯 !</em></p><p>AWS，即<ruby>亚马逊 Web 服务<rt>Amazon Web Services</rt></ruby>，是一个提供了一系列按使用计费的 web 服务的云平台。 它是迄今为止最为著名的云平台之一。由于其灵活性、有效性、弹性、可测量性和无须维护，所以有一些企业正逐步把他们的业务迁移到云端。 由于许多公司目前在使用这些服务，所以对于系统管理员和运维人员来说\b应该了解一下 AWS。</p><p>这篇文章旨在列出这些 AWS 提供的服务并且解释在 AWS 中出现的术语。</p><p>截止到目前为止（2017 年 3 月），AWS 提供了分为 17 组的共计 71 种服务：</p><h3 id="计算型服务" tabindex="-1">计算型服务 <a class="header-anchor" href="#计算型服务" aria-label="Permalink to “计算型服务”">​</a></h3><p>这是一个提供了虚拟服务器配置功能的服务，即所谓的云计算。它提供了包括以下这一系列的服务。</p><ol><li>EC2：EC2 代表弹性计算云。这种服务提供了可根据个人需求扩展的 [虚拟机][11]。</li><li>EC2 容器服务：其高性能，高可扩展性使其可在 EC2 集群环境中运行服务。</li><li>Lightsail：该服务使用户非常容易地启动和管理虚拟服务器（EC2）。</li><li>Elastic Beanstalk：该服务能够自动管理你的应用程序的容量配置、负载平衡、扩展以及健康监控从而减少你的管理压力。</li><li>Lambda：它允许你只在你需要的时候运行代码而不用去管理服务器。</li><li>Batch：它使用户能够以自定义的管理方式运行计算工作负载（批处理）。</li></ol><h3 id="存储型服务" tabindex="-1">存储型服务 <a class="header-anchor" href="#存储型服务" aria-label="Permalink to “存储型服务”">​</a></h3><p>它是一种云存储服务，即由 Amazon 提供的云存储设施。 该组服务包括：</p><ol><li>S3：S3 代表简单存储服务（3 个 S）。 它给你提供了在线存储服务，你可随时从任何地方存储/检索任何数据。</li><li>EFS：EFS 代表弹性文件系统。 它是一个可以和 EC2 服务器一起使用的在线存储服务。</li><li>Glacier：它是一种低成本/低性能数据存储解决方案，主要针对存档或长期备份。</li><li>Storage Gateway：这种服务的接口会将你的内部应用程序（托管在 AWS 之外）与 AWS 存储连接。</li></ol><h3 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to “数据库”">​</a></h3><p>AWS 还提供在其基础设施上托管数据库，以便客户可以利用亚马逊最先进的技术来获得更快/高效/安全的数据处理。 该组包括：</p><ol><li>RDS：RDS 代表关系数据库服务。 用于在云上设置，操作和管理关系数据库。</li><li>DynamoDB：其 NoSQL 数据库提供了快速处理和高可扩展性。</li><li>ElastiCache：这是一种为你的 Web 应用程序管理内存缓存以便更快运行它们的方案 ！</li><li>Redshift：它是一个巨大的（PB 级）的完全可升级的云端数据仓库服务。</li></ol><h3 id="网络-内容分发" tabindex="-1">网络 &amp; 内容分发 <a class="header-anchor" href="#网络-内容分发" aria-label="Permalink to “网络 &amp; 内容分发”">​</a></h3><p>由于 AWS 提供云端的 EC2 服务器，因此网络相关内容也将在出现在这里。 内容分发用于向位于最近位置的用户提供文件。 现如今有许多非常有名的加速网站。</p><ol><li>VPC：VPC 代表虚拟私有云。 它是你自己的虚拟网络，是你的专用 AWS 帐户。</li><li>CloudFront：这是 AWS 的内容分发网络（CDN）服务。</li><li>Direct Connect：它是将数据中心/场所与 AWS 连接起来的网络方式，以提高吞吐量，降低网络成本，并避免由于基于互联网的连接而导致的连接问题。</li><li>Route 53：它是一个云端的域名系统的 DNS Web 服务。</li></ol><h3 id="迁移" tabindex="-1">迁移 <a class="header-anchor" href="#迁移" aria-label="Permalink to “迁移”">​</a></h3><p>它提供了一系列服务来帮助你实现本地服务到 AWS 的迁移工作。 这包括 ：</p><ol><li>Application Discovery Service：专门用于分析您的服务器、网络、应用程序以帮助/加速迁移的服务。</li><li>DMS：DMS 指的是数据库迁移服务。 它用于将数据从本地数据库迁移到 EC2 上托管的 RDS 或 DB。</li><li>Server Migration：也称为 SMS（服务器迁移服务）是一种无代理服务，将您的工作负载从本地移动到 AWS。</li><li>Snowball： 当你想要使用物理存储设备（而不是基于互联网/基于网络的传输）将大量数据传入/迁出 AWS 时，你应该使用它。</li></ol><h3 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to “开发者工具”">​</a></h3><p>顾名思义, 这是一系列帮助开发者简化在云端编码的服务。</p><ol><li>CodeCommit：它是一个安全的、可扩展的、可管理的源代码管理服务，用于托管代码仓库。</li><li>CodeBuild：这是一个云端的代码生成器。主要用于执行、测试代码和构建部署软件包。</li><li>CodeDeploy：\b这是一个可在 AWS 服务器或本地进行自动化应用程序部署的部署服务。</li><li>CodePipeline：这个部署服务可以使编码人员可以在发布之前将其应用程序可视化。</li><li>X-Ray：它可以使用事件调用分析应用程序。</li></ol><h3 id="管理工具" tabindex="-1">管理工具 <a class="header-anchor" href="#管理工具" aria-label="Permalink to “管理工具”">​</a></h3><p>这是一组可帮助你管理 AWS 上的 Web 服务的服务。</p><ol><li>CloudWatch：监控你的 AWS 资源或应用程序的监控服务。</li><li>CloudFormation：基础设施即代码！以集体有序的方式管理 AWS 架构的方式。</li><li>CloudTrail：AWS 帐户的审计和合规工具。</li><li>Config : AWS 的资源清单、配置历史记录和配置更改通知，以实现安全性和治理。</li><li>OpsWorks：它可以自动化地配置，部署 EC2 或内部部署计算。</li><li>Service Catalog：创建和管理被批准在你/公司帐户中使用的 IT 服务目录。</li><li>Trusted Advisor：\b它的 AWS AI 可以通过审查你的 AWS 基础设施使你的 AWS 基础设施更好，更省钱\b。</li><li>Managed Service：提供持续的基础设施管理。</li></ol><h3 id="安全性、身份和合规" tabindex="-1">安全性、身份和合规 <a class="header-anchor" href="#安全性、身份和合规" aria-label="Permalink to “安全性、身份和合规”">​</a></h3><p>这是一组很重要的 AWS 服务以确保你的 AWS 空间的安全性。</p><ol><li>IAM：IAM 即身份和访问管理，控制用户访问你的 AWS 资源和服务。</li><li>Inspector：自动安全评估可帮助你在 AWS 上的应用安全和合规。</li><li>Certificate Manager：为 AWS 应用程序提供，管理和部署 SSL / TLS 证书。</li><li>Directory Service：相当于 AWS 的 Microsoft Active Directory。</li><li>WAF &amp; Shield：WAF 即 Web 应用防火墙。 监控和控制对 CloudFront 或负载均衡器上的内容的访问。</li><li>Compliance Reports：AWS 基础设施空间的合规报告，以确保您的应用程序符合您的策略。</li></ol><h3 id="数据分析" tabindex="-1">数据分析 <a class="header-anchor" href="#数据分析" aria-label="Permalink to “数据分析”">​</a></h3><p>AWS 空间的数据分析服务，以帮助您查看、计划和对帐户中的事件采取行动。</p><ol><li>Athena：它是一个基于 SQL 查询的服务，用于分析 S3 存储的数据。</li><li>EMR：EMR 的全写是 Elastic Map Reduce。 \b是一个主要用于大数据处理和分析的服务。</li><li>CloudSearch：AWS 在应用和服务中的搜索功能。</li><li>Elasticsearch Service：它可以创建一个域并在 AWS Cloud 中部署、操作和扩展 Elasticsearch 集群。</li><li>Kinesis：这种服务可以实现实时的大量流数据处理。</li><li>Data Pipeline：它可以帮助我们在不同的 AWS 服务之间实现数据迁移。</li><li>QuickSight：收集、分析和呈现 AWS 的业务数据。</li></ol><h3 id="人工智能" tabindex="-1">人工智能 <a class="header-anchor" href="#人工智能" aria-label="Permalink to “人工智能”">​</a></h3><p>AWS 的 AI!</p><ol><li>Lex：它可以帮助我们在一些使用语音和文本的应用中构建会话界面。</li><li>Polly：这是一个提供文字到语音转换的服务。</li><li>Rekognition：使您能够将图像分析添加到应用程序。</li><li>Machine Learning：它具有学习数据中的模式的算法。</li></ol><h3 id="物联网" tabindex="-1">物联网 <a class="header-anchor" href="#物联网" aria-label="Permalink to “物联网”">​</a></h3><p>这个服务保证了 AWS 在不同设备上的高可用性。</p><ol><li>AWS IoT：它使联网硬件设备与 AWS 的应用程序能够交互。</li></ol><h3 id="游戏开发" tabindex="-1">游戏开发 <a class="header-anchor" href="#游戏开发" aria-label="Permalink to “游戏开发”">​</a></h3><p>顾名思义，这个服务旨在游戏开发。</p><ol><li>Amazon GameLift：该服务旨在部署、管理用于会话的多人游戏的专用游戏服务器。</li></ol><h3 id="移动服务" tabindex="-1">移动服务 <a class="header-anchor" href="#移动服务" aria-label="Permalink to “移动服务”">​</a></h3><p>这是一组主要针对手持设备的服务。</p><ol><li>Mobile Hub：帮助您创建移动应用的后台功能并将其集成到移动应用。</li><li>Cognito：在连接了互联网设备上控制移动用户的身份验证和 AWS 的访问。</li><li>Device Farm：移动应用测试服务使你可以在 Android 上托管的真实手机上跨 Android、iOS 测试应用。</li><li>Mobile Analytics：在 AWS 上测量、跟踪和分析移动应用数据。</li><li>Pinpoint：针对性的推送通知和移动互动。</li></ol><h3 id="应用服务" tabindex="-1">\b应用服务 <a class="header-anchor" href="#应用服务" aria-label="Permalink to “\b应用服务”">​</a></h3><p>这是一组\b可以和你在 AWS 上的应用一起使用的服务。</p><ol><li>Step Functions：定义和使用应用程序中的各种功能。</li><li>SWF：SWF 代表简单的工作流服务。其云工作流程管理可帮助开发人员在应用程序生命周期的不同阶段进行协调和贡献。</li><li>API Gateway：帮助开发人员创建、管理和托管 API。</li><li>Elastic Transcoder：帮助开发人员将媒体文件转换为在各种设备上可以播放的格式。</li></ol><h3 id="消息" tabindex="-1">消息 <a class="header-anchor" href="#消息" aria-label="Permalink to “消息”">​</a></h3><p>AWS 中的通知和消息服务。</p><ol><li>SQS：SQS 表示简单队列服务。完全管理的消息队列服务，用于在 AWS 中的服务和应用之间进行通信。</li><li>SNS：SNS 代表简单通知服务。 为 AWS 用户推送通知服务，提醒他们有关其在 AWS 空间中的服务。</li><li>SES：SES 代表简单电子邮件服务。 这是 AWS 为自己的客户提供高性价比的电子邮件服务。</li></ol><h3 id="企业生产率" tabindex="-1">企业生产率 <a class="header-anchor" href="#企业生产率" aria-label="Permalink to “企业生产率”">​</a></h3><p>一组帮你提高业务生产率的服务。</p><ol><li>WorkDocs：协同文件共享、存储和编辑服务。</li><li>WorkMail：安全的商务邮件、日程服务。</li><li>Amazon Chime：在线的企业会议！</li></ol><h3 id="桌面和应用程序流式传输" tabindex="-1">桌面和应用程序流式传输 <a class="header-anchor" href="#桌面和应用程序流式传输" aria-label="Permalink to “桌面和应用程序流式传输”">​</a></h3><p>实现桌面应用程序通过云端进行流传输。</p><ol><li>WorkSpaces：完全管理且安全的云计算服务。</li><li>AppStream 2.0：来自云端的流式桌面应用。</li></ol><hr>',58)),t("p",null,[l[1]||(l[1]=i("via: ",-1)),e(a,{href:"http://kerneltalks.com/virtualization/aws-cloud-terminology/"},{default:o(()=>[...l[0]||(l[0]=[i("http://kerneltalks.com/virtualization/aws-cloud-terminology/",-1)])]),_:1})]),t("p",null,[l[5]||(l[5]=i("作者：",-1)),e(a,{href:"http://kerneltalks.com/virtualization/aws-cloud-terminology/"},{default:o(()=>[...l[2]||(l[2]=[i("Shrikant Lavhate",-1)])]),_:1}),l[6]||(l[6]=i(" 译者：",-1)),e(a,{href:"https://github.com/chenxinlong"},{default:o(()=>[...l[3]||(l[3]=[i("chenxinlong",-1)])]),_:1}),l[7]||(l[7]=i(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:o(()=>[...l[4]||(l[4]=[i("wxy",-1)])]),_:1})]),t("p",null,[l[10]||(l[10]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...l[8]||(l[8]=[i("LCTT",-1)])]),_:1}),l[11]||(l[11]=i(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:o(()=>[...l[9]||(l[9]=[i("Linux中国",-1)])]),_:1}),l[12]||(l[12]=i(" 荣誉推出",-1))])])}const k=r(h,[["render",p]]);export{f as __pageData,k as default};
